    mat[3] = sy * sp; mat[4] = cp; mat[5] = 0;
    canvas.concat(mat);
    mat[0] = a; mat[1] = b; mat[2] = shift * ex - 50 * a - 50 * b;
    mat[3] = b; mat[4] = d; mat[5] = shift * ey - 50 * b - 50 * d;
