  const data = new Uint8Array(NN * 4);
  for (let i = 0; i < NN; i++) {
    const a = form.ao[i];
    const cell = form.i00[i], cx = cell % M, cy = (cell - cx) / M;
    const k = i * 4;
    data[k] = a ? Math.round((255 * (cx + form.wx[i] / 255)) / (M - 1)) : 128;
    data[k + 1] = a ? Math.round((255 * (cy + form.wy[i] / 255)) / (M - 1)) : 128;
