const ENV: V3 = [0.92, 0.96, 1.0];
const WARM: V3 = [1, 0.98, 0.95];
const KD = 0.85;
const TONE_N = 2048;
const TONE_MAX = 2.5;
const TONE_SCALE = TONE_N / TONE_MAX;
const POW_N = 1024;

export function lightConstants(c: V3, p: LightMaterial): LightConstants {
